    expect(w.get('[data-test="reminders-empty"]').text()).toBe('No history reminders.');
    expect(status(w)).toBe('History, no reminders');
    // Past the last tab: wrap to the first. And back with [.
    await key(']', {}, active());
    expect(tabState(w)).toBe('Pending 2');
